      const totalContract = projectForm.tariff?.amount || 0;
      const totalInvoiced = (projectForm.invoices || []).reduce((acc, inv) => acc + inv.total, 0);
      const totalPaid = projectForm.payments.reduce((acc, p) => acc + p.amount, 0);
      const balance = totalContract - totalPaid;
      return { totalContract, totalInvoiced, totalPaid, balance };
  };

