      const mentionRegex = /@([a-zA-Z0-9_]+)/g;
      const matches = text.match(mentionRegex);
      if (!matches) return;
      const uniqueMentions = [...new Set(matches)];
      for (const mention of uniqueMentions) {
          const username = mention.substring(1);
          const targetUser = personnel.find(p => p.username === username);
          if (targetUser && targetUser.id !== currentUser.id) {
              const msg: InternalMessage = {
                  id: `n-${Date.now()}-${Math.random()}`,
                  senderId: currentUser.id,
                  senderName: 'System',
                  recipientIds: [targetUser.id],
                  recipientNames: [targetUser.fullName],
                  subject: `Mentioned in ${sourceTitle}`,
                  body: `${currentUser.fullName} mentioned you:\n\n"${text}"\n\nID: ${sourceId}`,
                  createdAt: new Date().toISOString(),
                  readBy: []
              };
              await sendInternalMessage(msg);
          }
      }
  };

