                                <div key={field.id} className="space-y-2">
                                    {field.type === 'header' ? (
                                        <h4 className="font-bold text-lg text-gray-800 border-b border-gray-200 pb-2 mt-6">{field.label}</h4>
                                    ) : (
                                        <>
                                            <label className="block text-sm font-bold text-gray-700">
                                                {field.label} {field.required && <span className="text-red-500">*</span>}
                                            </label>
                                            {field.type === 'textarea' ? (
                                                <textarea className="w-full border border-gray-300 rounded-lg p-3 outline-none focus:ring-2 focus:ring-indigo-500" rows={4} placeholder={field.placeholder} />
                                            ) : field.type === 'select' ? (
                                                <select className="w-full border border-gray-300 rounded-lg p-3 outline-none focus:ring-2 focus:ring-indigo-500 bg-white">
                                                    <option value="">-</option>
                                                    {field.options?.map((opt, i) => <option key={i} value={opt}>{opt}</option>)}
                                                </select>
                                            ) : field.type === 'checkbox' ? (
                                                <input type="checkbox" className="w-5 h-5 text-indigo-600 rounded" />
                                            ) : (
                                                <input 
                                                    type={field.type} 
                                                    className="w-full border border-gray-300 rounded-lg p-3 outline-none focus:ring-2 focus:ring-indigo-500" 
                                                    placeholder={field.placeholder} 
                                                />
                                            )}
                                        </>
                                    )}
                                </div>
                            ))}
                            <div className="pt-6 border-t border-gray-100 flex justify-end">
                                <button className="bg-indigo-600 text-white px-8 py-3 rounded-xl font-bold shadow-lg shadow-indigo-200 hover:bg-indigo-700">ثبت فرم</button>
                            </div>
                        </div>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {customForms.length > 0 ? customForms.map(form => (
                            <div key={form.id} onClick={() => setSelectedCustomForm(form)} className="bg-white p-6 rounded-2xl border border-gray-200 shadow-sm hover:shadow-lg hover:border-indigo-300 transition-all cursor-pointer group">
                                <div className="flex items-start justify-between mb-4">
                                    <div className="p-3 bg-indigo-50 text-indigo-600 rounded-xl group-hover:bg-indigo-600 group-hover:text-white transition-colors">
                                        <IconFolder className="w-6 h-6" />
                                    </div>
                                    <span className="text-xs font-bold text-gray-400 bg-gray-50 px-2 py-1 rounded">{form.category}</span>
                                </div>
                                <h3 className="text-lg font-bold text-gray-900 mb-2 group-hover:text-indigo-600 transition-colors">{form.title}</h3>
                                <p className="text-sm text-gray-500 line-clamp-2 h-10">{form.description || 'بدون توضیحات'}</p>
                                <div className="mt-4 pt-4 border-t border-gray-50 flex justify-between items-center text-xs text-gray-400">
                                    <span>{form.fields.length} فیلد</span>
                                    <span className="text-indigo-500 font-bold opacity-0 group-hover:opacity-100 transition-opacity">{t.selectForm} →</span>
                                </div>
                            </div>
                        )) : (
                            <div className="col-span-full py-12 text-center bg-white rounded-2xl border border-dashed border-gray-300">
                                <IconClipboard className="w-12 h-12 text-gray-300 mx-auto mb-3" />
                                <p className="text-gray-500 font-bold">هیچ فرمی برای نمایش وجود ندارد.</p>
                                <p className="text-xs text-gray-400 mt-1">فرم‌های جدید را می‌توانید از بخش تنظیمات ایجاد کنید.</p>
                            </div>
                        )}
                    </div>
                )}
            </div>
        )}

        {activeTab === 'messages' && <InternalMessenger currentUser={currentUser} personnel={personnel} messages={messages} lang={lang} />}
        {activeTab === 'tasks' && <TaskManager currentUser={currentUser} personnel={personnel} tasks={tasks} lang={lang} />}
        {activeTab === 'meetings' && <MeetingCalendar meetings={meetings} currentUser={currentUser} personnel={personnel} lang={lang} />}
        {activeTab === 'customers' && hasCustomerAccess && <CustomerManager customers={customers} currentUser={currentUser} onUpdate={onUpdateCustomers} onEdit={onEditCustomer} onDelete={onDeleteCustomer} lang={lang} />}
        {activeTab === 'services' && hasTariffAccess && <ServiceManager services={services} onUpdate={onUpdateServices} readonly={!isAdmin && !isMaster} lang={lang} />}
        {activeTab === 'personnel' && isAdmin && <PersonnelManager personnel={personnel} config={config} onUpdate={onUpdatePersonnel} onUpdateConfig={onUpdateConfig} lang={lang} />}
        {activeTab === 'settings' && isAdmin && <SettingsManager config={config} onUpdate={onUpdateConfig} isMaster={isMaster} />}
        {activeTab === 'reports' && isMaster && <PerformanceReports personnel={personnel} tickets={tickets} tasks={tasks} lang={lang} />}
        {activeTab === 'kpi' && isMaster && <KPIManager kpis={kpis} personnel={personnel} lang={lang} />}
        {activeTab === 'logs' && isMaster && (
            <div className="space-y-4 animate-fade-in">
                <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm"><h2 className="text-xl font-bold text-gray-800 flex items-center gap-2"><IconHistory className="w-6 h-6" /> {t.auditLogs}</h2></div>
                <div className="bg-white rounded-2xl border border-gray-200 overflow-hidden"><table className="w-full text-start text-sm"><thead className="bg-gray-50 text-gray-500"><tr><th className="px-4 py-3">{t.time}</th><th className="px-4 py-3">{t.user}</th><th className="px-4 py-3">{t.operation}</th><th className="px-4 py-3">{t.entity}</th><th className="px-4 py-3">{t.details}</th><th className="px-4 py-3">{t.action}</th></tr></thead><tbody className="divide-y divide-gray-100">{systemLogs.map(log => (<tr key={log.id} className="hover:bg-gray-50"><td className="px-4 py-3 text-gray-500 dir-ltr text-right">{new Date(log.timestamp).toLocaleString(lang === 'fa' ? 'fa-IR' : 'en-US')}</td><td className="px-4 py-3 font-bold text-gray-700">{log.actorName}</td><td className="px-4 py-3"><span className={`px-2 py-1 rounded text-xs font-bold ${log.actionType === 'DELETE' ? 'bg-red-100 text-red-700' : (log.actionType === 'CREATE' ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700')}`}>{log.actionType}</span></td><td className="px-4 py-3">{log.entity}</td><td className="px-4 py-3 text-gray-600 truncate max-w-xs" title={log.details}>{log.details}</td><td className="px-4 py-3">{log.actionType === 'DELETE' && log.backupData && (<button onClick={() => handleRestore(log)} className="text-blue-600 hover:bg-blue-50 px-2 py-1 rounded flex items-center gap-1 font-bold text-xs"><IconRefreshCw className="w-3 h-3" /> {t.restore}</button>)}</td></tr>))}</tbody></table>{systemLogs.length === 0 && <div className="p-8 text-center text-gray-400">{t.noLogs}</div>}</div>
            </div>
        )}
        {activeTab === 'financial' && (isAdmin || isMaster) && renderFinancialReport()}
      </div>

      {selectedTicket && renderTicketModal()}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Task, Personnel, TaskComment, InternalMessage, TaskChecklistItem } from '../types';
import { IconCheckSquare, IconPlus, IconList, IconUsers, IconMessageSquare, IconTrash, IconClock, IconSend, IconEdit, IconCheck, IconSearch } from './Icons';
import { saveTaskToCloud, updateTaskInCloud, deleteTaskFromCloud, sendInternalMessage } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  tasks: Task[];
  lang: Language;
}

export const TaskManager: React.FC<Props> = ({ currentUser, personnel, tasks, lang }) => {
  const [showAddModal, setShowAddModal] = useState(false);
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [isEditing, setIsEditing] = useState(false); // State to toggle edit mode
  const [editingTaskData, setEditingTaskData] = useState<Partial<Task>>({}); // State for editing data

  const [filterMode, setFilterMode] = useState<'my' | 'assigned' | 'all'>('my');
  const [newTaskTitle, setNewTaskTitle] = useState('');
  const [newTaskDesc, setNewTaskDesc] = useState('');
  const [newTaskPriority, setNewTaskPriority] = useState<'Low' | 'Medium' | 'High'>('Medium');
  const [newTaskAssignees, setNewTaskAssignees] = useState<string[]>([currentUser.id]);
  const [newTaskChecklist, setNewTaskChecklist] = useState<TaskChecklistItem[]>([]);
  const [tempChecklistItem, setTempChecklistItem] = useState('');

  // Comment states
  const [newComment, setNewComment] = useState('');
  const [showMentionList, setShowMentionList] = useState(false);
  const commentsEndRef = useRef<HTMLDivElement>(null);
  const isAdmin = currentUser.roles.includes('مدیر') || currentUser.username === 'master';

  const t = {
      fa: {
          header: 'امور روزانه و وظایف تیمی',
          sub: 'مدیریت لیست کارها، چک‌لیست‌ها و پیگیری',
          myTasks: 'کارهای من',
          assigned: 'محول شده‌ها',
          all: 'همه',
          newTask: 'تعریف کار جدید',
          title: 'عنوان کار',
          desc: 'توضیحات',
          checklist: 'چک‌لیست / زیرمجموعه کارها',
          add: 'افزودن',
          priority: 'اولویت',
          team: 'انجام دهندگان (تیم)',
          create: 'ثبت وظیفه',
          chat: 'گفتگو و پیگیری',
          writeMsg: 'نوشتن پیام...',
          deleteConfirm: 'آیا از حذف این وظیفه اطمینان دارید؟',
          low: 'پایین',
          medium: 'عادی',
          high: 'فوری',
          empty: 'لیست کارها خالی است.',
          mention: 'منشن کردن همکار (@)',
          edit: 'ویرایش',
          save: 'ذخیره تغییرات',
          cancel: 'انصراف',
          itemPlaceholder: 'آیتم جدید...'
      },
      en: {
          header: 'Daily Tasks & Team Work',
          sub: 'Manage tasks, checklists and tracking',
          myTasks: 'My Tasks',
          assigned: 'Assigned by Me',
          all: 'All',
          newTask: 'New Task',
          title: 'Title',
          desc: 'Description',
          checklist: 'Checklist / Subtasks',
          add: 'Add',
          priority: 'Priority',
          team: 'Assignees',
          create: 'Create Task',
          chat: 'Chat & Tracking',
          writeMsg: 'Write a comment...',
          deleteConfirm: 'Are you sure you want to delete this task?',
          low: 'Low',
          medium: 'Normal',
          high: 'Urgent',
          empty: 'No tasks found.',
          mention: 'Mention colleague (@)',
          edit: 'Edit',
          save: 'Save Changes',
          cancel: 'Cancel',
          itemPlaceholder: 'New item...'
      }
  }[lang];

  useEffect(() => {
    if (selectedTask && commentsEndRef.current) { commentsEndRef.current.scrollIntoView({ behavior: 'smooth' }); }
  }, [selectedTask?.comments?.length]);

  // Reset editing state when modal closes
  useEffect(() => {
      if (!selectedTask) {
          setIsEditing(false);
          setEditingTaskData({});
      }
  }, [selectedTask]);

  const filteredTasks = tasks.filter(task => {
      if (filterMode === 'my') return task.assigneeIds.includes(currentUser.id);
      if (filterMode === 'assigned') return task.creatorId === currentUser.id;
      return true;
  });

  const handleAddChecklistItemCreate = () => {
      if (!tempChecklistItem.trim()) return;
      setNewTaskChecklist(prev => [...prev, { id: `cl-${Date.now()}`, text: tempChecklistItem, isCompleted: false }]);
      setTempChecklistItem('');
  };

  const handleCreateTask = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!newTaskTitle.trim()) return;
      const newTask: Task = { id: `task-${Date.now()}`, title: newTaskTitle, description: newTaskDesc, creatorId: currentUser.id, creatorName: currentUser.fullName, assigneeIds: newTaskAssignees, isCompleted: false, priority: newTaskPriority, createdAt: new Date().toISOString(), checklist: newTaskChecklist, comments: [] };
      await saveTaskToCloud(newTask);
      setShowAddModal(false); setNewTaskTitle(''); setNewTaskDesc(''); setNewTaskAssignees([currentUser.id]); setNewTaskChecklist([]); setTempChecklistItem('');
  };

  const toggleTaskCompletion = async (task: Task) => { await updateTaskInCloud(task.id, { isCompleted: !task.isCompleted }); };
  const handleDeleteTask = async (id: string) => { if (window.confirm(t.deleteConfirm)) { await deleteTaskFromCloud(id); if (selectedTask?.id === id) setSelectedTask(null); } };

  // --- Editing Logic ---
  const handleStartEdit = () => {
      if (!selectedTask) return;
      setEditingTaskData({
          title: selectedTask.title,
          description: selectedTask.description,
          priority: selectedTask.priority,
          assigneeIds: selectedTask.assigneeIds,
          checklist: selectedTask.checklist || []
      });
      setIsEditing(true);
  };

  const handleSaveEdit = async () => {
      if (!selectedTask || !editingTaskData.title) return;
      await updateTaskInCloud(selectedTask.id, editingTaskData);

      // Update local state to reflect changes immediately
      setSelectedTask({ ...selectedTask, ...editingTaskData } as Task);
      setIsEditing(false);
  };

  const handleEditChecklistText = (id: string, text: string) => {
      setEditingTaskData(prev => ({
          ...prev,
          checklist: prev.checklist?.map(item => item.id === id ? { ...item, text } : item)
      }));
  };

  const handleAddChecklistItemEdit = () => {
      if (!tempChecklistItem.trim()) return;
      const newItem: TaskChecklistItem = { id: `cl-${Date.now()}`, text: tempChecklistItem, isCompleted: false };
      setEditingTaskData(prev => ({
          ...prev,
          checklist: [...(prev.checklist || []), newItem]
      }));
      setTempChecklistItem('');
  };

  const handleRemoveChecklistItemEdit = (id: string) => {
      setEditingTaskData(prev => ({
          ...prev,
          checklist: prev.checklist?.filter(item => item.id !== id)
      }));
  };

  const toggleAssigneeEdit = (userId: string) => {
      setEditingTaskData(prev => {
          const currentIds = prev.assigneeIds || [];
          if (currentIds.includes(userId)) {
              return { ...prev, assigneeIds: currentIds.filter(id => id !== userId) };
          } else {
              return { ...prev, assigneeIds: [...currentIds, userId] };
          }
      });
  };
  // ---------------------

  const processMentions = async (text: string, sourceTitle: string, sourceId: string) => {
      const mentionRegex = /@([a-zA-Z0-9_]+)/g;
      const matches = text.match(mentionRegex);
      if (!matches) return;
      const uniqueMentions = [...new Set(matches)];
      for (const mention of uniqueMentions) {
          const username = mention.substring(1);
          const targetUser = personnel.find(p => p.username === username);
          if (targetUser && targetUser.id !== currentUser.id) {
              const msg: InternalMessage = { id: `n-${Date.now()}-${Math.random()}`, senderId: currentUser.id, senderName: 'System', recipientIds: [targetUser.id], recipientNames: [targetUser.fullName], subject: `Mentioned in Task "${sourceTitle}"`, body: `${currentUser.fullName} mentioned you:\n\n"${text}"\n\nTask ID: ${sourceId}`, createdAt: new Date().toISOString(), readBy: [] };
              await sendInternalMessage(msg);
          }
      }
  };

  const handleAddComment = async () => {
      if (!selectedTask || !newComment.trim()) return;
      await processMentions(newComment, selectedTask.title, selectedTask.id);
      const comment: TaskComment = { id: `cm-${Date.now()}`, authorId: currentUser.id, authorName: currentUser.fullName, text: newComment, timestamp: new Date().toISOString() };
      const updatedComments = [...(selectedTask.comments || []), comment];
      await updateTaskInCloud(selectedTask.id, { comments: updatedComments });
      setSelectedTask({ ...selectedTask, comments: updatedComments });
      setNewComment(''); setShowMentionList(false);
  };

  const handleInsertMention = (username: string) => { setNewComment(prev => prev + `@${username} `); setShowMentionList(false); };

  // Checklist Toggle (View Mode)
  const handleToggleChecklist = async (itemId: string) => { 
      if (!selectedTask) return; 
      const updatedChecklist = (selectedTask.checklist || []).map(item => item.id === itemId ? { ...item, isCompleted: !item.isCompleted } : item); 
      await updateTaskInCloud(selectedTask.id, { checklist: updatedChecklist }); 
      setSelectedTask({ ...selectedTask, checklist: updatedChecklist }); 
  };

  // Checklist Delete (View Mode) - kept for quick action if needed, though edit mode is better
  const handleDeleteChecklistItem = async (itemId: string) => { 
      if (!selectedTask) return; 
      if(!window.confirm('Delete item?')) return;
      const updatedChecklist = (selectedTask.checklist || []).filter(item => item.id !== itemId); 
      await updateTaskInCloud(selectedTask.id, { checklist: updatedChecklist }); 
      setSelectedTask({ ...selectedTask, checklist: updatedChecklist }); 
  };

  // Checklist Add (View Mode)
  const handleAddChecklistItemView = async () => { 
      if (!selectedTask || !tempChecklistItem.trim()) return; 
      const newItem: TaskChecklistItem = { id: `cl-${Date.now()}`, text: tempChecklistItem, isCompleted: false }; 
      const updatedChecklist = [...(selectedTask.checklist || []), newItem]; 
      await updateTaskInCloud(selectedTask.id, { checklist: updatedChecklist }); 
      setSelectedTask({ ...selectedTask, checklist: updatedChecklist }); 
      setTempChecklistItem(''); 
  };

  const getPriorityColor = (p: string) => { if (p === 'High') return 'bg-red-100 text-red-600 border-red-200'; if (p === 'Medium') return 'bg-yellow-100 text-yellow-700 border-yellow-200'; return 'bg-blue-100 text-blue-600 border-blue-200'; };
  const calculateProgress = (checklist: TaskChecklistItem[] = []) => { if (checklist.length === 0) return 0; const completed = checklist.filter(i => i.isCompleted).length; return Math.round((completed / checklist.length) * 100); };

  return (
    <div className="space-y-6 animate-fade-in">
        <div className="flex flex-col md:flex-row justify-between items-center bg-white p-6 rounded-2xl border border-gray-100 shadow-sm gap-4"><div><h2 className="text-xl font-bold text-gray-800 flex items-center gap-2"><div className="bg-indigo-100 text-indigo-600 p-2 rounded-lg"><IconList className="w-6 h-6" /></div>{t.header}</h2><p className="text-sm text-gray-500 mt-1">{t.sub}</p></div><div className="flex gap-2"><div className="flex bg-gray-100 p-1 rounded-lg"><button onClick={() => setFilterMode('my')} className={`px-4 py-1.5 rounded-md text-sm font-bold transition-all ${filterMode === 'my' ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}>{t.myTasks}</button><button onClick={() => setFilterMode('assigned')} className={`px-4 py-1.5 rounded-md text-sm font-bold transition-all ${filterMode === 'assigned' ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}>{t.assigned}</button>{isAdmin && <button onClick={() => setFilterMode('all')} className={`px-4 py-1.5 rounded-md text-sm font-bold transition-all ${filterMode === 'all' ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}>{t.all}</button>}</div><button onClick={() => setShowAddModal(true)} className="bg-indigo-600 text-white px-4 py-2 rounded-xl font-bold hover:bg-indigo-700 flex items-center gap-2 shadow-lg shadow-indigo-200"><IconPlus className="w-5 h-5" /> {t.newTask}</button></div></div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredTasks.map(task => { 
                const progress = calculateProgress(task.checklist); 
                return (
                    <div key={task.id} className={`bg-white rounded-2xl border shadow-sm p-4 transition-all hover:shadow-md relative flex flex-col ${task.isCompleted ? 'border-gray-200 bg-gray-50' : 'border-gray-200'}`}>
                        <div className="flex justify-between items-start mb-3">
                            <div className="flex items-center gap-3">
                                <button onClick={() => toggleTaskCompletion(task)} className={`w-6 h-6 rounded border flex items-center justify-center transition-colors ${task.isCompleted ? 'bg-green-500 border-green-500 text-white' : 'border-gray-300 hover:border-indigo-500'}`}>{task.isCompleted && <IconCheckSquare className="w-4 h-4" />}</button>
                                <span className={`font-bold text-gray-800 cursor-pointer hover:text-indigo-600 ${task.isCompleted ? 'line-through text-gray-400' : ''}`} onClick={() => setSelectedTask(task)}>{task.title}</span>
                            </div>
                            <span className={`text-[10px] px-2 py-0.5 rounded border ${getPriorityColor(task.priority)}`}>{task.priority}</span>
                        </div>
                        <p className={`text-sm text-gray-500 mb-4 line-clamp-2 cursor-pointer ${task.isCompleted ? 'line-through opacity-50' : ''}`} onClick={() => setSelectedTask(task)}>{task.description || '-'}</p>

                        {task.checklist && task.checklist.length > 0 && (
                            <div className="mb-4">
                                <div className="flex justify-between text-[10px] text-gray-400 mb-1"><span>{t.checklist}</span><span>{progress}%</span></div>
                                <div className="w-full bg-gray-100 rounded-full h-1.5 overflow-hidden"><div className="bg-green-500 h-full rounded-full transition-all" style={{ width: `${progress}%` }}></div></div>
                            </div>
                        )}

                        <div className="mt-auto flex justify-between items-end border-t border-gray-50 pt-3">
                            <div className="flex -space-x-2 space-x-reverse">{task.assigneeIds.map(uid => { const p = personnel.find(per => per.id === uid); return (<div key={uid} className="w-8 h-8 rounded-full bg-gray-200 border-2 border-white flex items-center justify-center text-xs font-bold text-gray-600" title={p?.fullName}>{p?.avatar ? <img src={p.avatar} className="w-full h-full rounded-full object-cover" /> : p?.fullName.charAt(0)}</div>); })}</div>
                            <div className="flex gap-2">
                                <button onClick={() => setSelectedTask(task)} className="text-gray-400 hover:text-indigo-600 flex items-center gap-1 text-xs font-bold bg-gray-50 px-2 py-1 rounded"><IconMessageSquare className="w-3 h-3" />{task.comments?.length || 0}</button>
                                {(task.creatorId === currentUser.id || isAdmin) && (<button onClick={() => handleDeleteTask(task.id)} className="text-gray-400 hover:text-red-500 p-1 rounded hover:bg-red-50"><IconTrash className="w-4 h-4" /></button>)}
                            </div>
                        </div>
                    </div>
                )
            })} 
            {filteredTasks.length === 0 && <div className="col-span-full py-12 text-center text-gray-400 bg-white rounded-2xl border border-dashed border-gray-200">{t.empty}</div>}
        </div>

        {/* CREATE TASK MODAL */}
        {showAddModal && (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4"><div className="bg-white rounded-2xl w-full max-w-lg shadow-2xl animate-fade-in flex flex-col max-h-[90vh]"><div className="p-5 border-b border-gray-100 flex justify-between items-center"><h3 className="font-bold text-gray-800">{t.newTask}</h3><button onClick={() => setShowAddModal(false)} className="text-gray-400 hover:text-gray-600">✕</button></div><div className="overflow-y-auto p-6 flex-grow"><form id="create-task-form" onSubmit={handleCreateTask} className="space-y-4"><div><label className="block text-sm font-bold text-gray-700 mb-1">{t.title}</label><input required className="w-full px-3 py-2 border border-gray-300 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500" value={newTaskTitle} onChange={e => setNewTaskTitle(e.target.value)} /></div><div><label className="block text-sm font-bold text-gray-700 mb-1">{t.desc}</label><textarea className="w-full px-3 py-2 border border-gray-300 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500" value={newTaskDesc} onChange={e => setNewTaskDesc(e.target.value)} rows={3} /></div><div className="bg-gray-50 p-3 rounded-lg border border-gray-200"><label className="block text-sm font-bold text-gray-700 mb-2">{t.checklist}</label><div className="space-y-2 mb-2">{newTaskChecklist.map((item, idx) => (<div key={idx} className="flex items-center gap-2 text-sm bg-white p-2 rounded border border-gray-200"><IconCheckSquare className="w-4 h-4 text-gray-400" /><span className="flex-grow">{item.text}</span><button type="button" onClick={() => setNewTaskChecklist(prev => prev.filter((_, i) => i !== idx))} className="text-red-400 hover:text-red-600"><IconTrash className="w-3 h-3" /></button></div>))}</div><div className="flex gap-2"><input className="flex-grow px-2 py-1.5 text-sm border border-gray-300 rounded outline-none" placeholder="..." value={tempChecklistItem} onChange={e => setTempChecklistItem(e.target.value)} onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); handleAddChecklistItemCreate(); } }} /><button type="button" onClick={handleAddChecklistItemCreate} className="bg-indigo-50 text-indigo-600 px-3 rounded text-xs font-bold border border-indigo-200 hover:bg-indigo-100">{t.add}</button></div></div><div className="grid grid-cols-2 gap-4"><div><label className="block text-sm font-bold text-gray-700 mb-1">{t.priority}</label><select className="w-full px-3 py-2 border border-gray-300 rounded-lg bg-white" value={newTaskPriority} onChange={e => setNewTaskPriority(e.target.value as any)}><option value="Low">{t.low}</option><option value="Medium">{t.medium}</option><option value="High">{t.high}</option></select></div></div><div><label className="block text-sm font-bold text-gray-700 mb-1">{t.team}</label><div className="flex flex-wrap gap-2 p-2 border border-gray-300 rounded-lg max-h-32 overflow-y-auto">{personnel.map(p => (<button key={p.id} type="button" onClick={() => setNewTaskAssignees(prev => prev.includes(p.id) ? prev.filter(id => id !== p.id) : [...prev, p.id])} className={`px-2 py-1 rounded text-xs font-bold border ${newTaskAssignees.includes(p.id) ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-gray-50 text-gray-600 border-gray-200'}`}>{p.fullName}</button>))}</div></div></form></div><div className="p-4 border-t border-gray-100 flex justify-end"><button type="submit" form="create-task-form" className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold hover:bg-indigo-700 shadow-lg shadow-indigo-200">{t.create}</button></div></div></div>
        )}

        {/* DETAIL & EDIT TASK MODAL */}
        {selectedTask && (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
                <div className="bg-white rounded-2xl w-full max-w-2xl h-[85vh] shadow-2xl animate-fade-in flex flex-col overflow-hidden">
                    <div className="p-5 border-b border-gray-100 flex justify-between items-start bg-gray-50 shrink-0">
                        <div className="w-full">
                            {isEditing ? (
                                <input 
                                    className="w-full text-xl font-bold text-gray-800 bg-white border border-gray-300 rounded px-2 py-1 outline-none focus:ring-2 focus:ring-indigo-500"
                                    value={editingTaskData.title || ''}
                                    onChange={e => setEditingTaskData({...editingTaskData, title: e.target.value})}
                                    placeholder={t.title}
                                />
                            ) : (
                                <div className="flex items-center gap-2 mb-1">
                                    <span className={`text-[10px] px-2 py-0.5 rounded border ${getPriorityColor(selectedTask.priority)}`}>{selectedTask.priority}</span>
                                    <span className="text-xs text-gray-400 dir-ltr">{new Date(selectedTask.createdAt).toLocaleString(lang === 'fa' ? 'fa-IR' : 'en-US')}</span>
                                    <h3 className={`font-bold text-xl text-gray-800 ${selectedTask.isCompleted ? 'line-through text-gray-400' : ''}`}>{selectedTask.title}</h3>
                                </div>
                            )}
                        </div>
                        <div className="flex gap-2 shrink-0 ml-4">
                            {!isEditing && (
                                <button onClick={handleStartEdit} className="text-gray-500 hover:text-indigo-600 p-1 rounded hover:bg-indigo-50">
                                    <IconEdit className="w-5 h-5" />
                                </button>
                            )}
                            <button onClick={() => setSelectedTask(null)} className="text-gray-400 hover:text-red-600 p-1 rounded hover:bg-red-50">✕</button>
                        </div>
                    </div>

                    <div className="flex-grow overflow-y-auto p-6 space-y-6">
                        {/* Description Section */}
                        {isEditing ? (
                            <div>
                                <label className="block text-xs font-bold text-gray-500 mb-1">{t.desc}</label>
                                <textarea 
                                    className="w-full p-3 border border-gray-300 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500 min-h-[100px]"
                                    value={editingTaskData.description || ''}
                                    onChange={e => setEditingTaskData({...editingTaskData, description: e.target.value})}
                                />
                            </div>
                        ) : (
                            <div className="bg-white p-4 rounded-xl border border-gray-100 text-gray-700 leading-relaxed whitespace-pre-wrap">
                                {selectedTask.description || '-'}
                            </div>
                        )}

                        {/* Checklist Section */}
                        <div className="bg-gray-50 rounded-xl border border-gray-200 p-4">
                            <div className="flex justify-between items-center mb-3">
                                <h4 className="font-bold text-gray-700 flex items-center gap-2 text-sm">
                                    <IconList className="w-4 h-4 text-indigo-500" /> {t.checklist}
                                </h4>
                                {!isEditing && <span className="text-xs font-bold text-indigo-600 bg-indigo-50 px-2 py-1 rounded">{calculateProgress(selectedTask.checklist)}%</span>}
                            </div>

                            <div className="space-y-2 mb-3">
                                {(isEditing ? (editingTaskData.checklist || []) : (selectedTask.checklist || [])).map(item => (
                                    <div key={item.id} className={`flex items-center gap-3 bg-white p-2 rounded-lg border ${isEditing ? 'border-gray-300' : 'border-gray-200 hover:border-indigo-300'} transition-colors group`}>
                                        {!isEditing && (
                                            <input type="checkbox" checked={item.isCompleted} onChange={() => handleToggleChecklist(item.id)} className="w-5 h-5 text-green-600 rounded cursor-pointer"/>
                                        )}

                                        {isEditing ? (
                                            <input 
                                                className="flex-grow text-sm outline-none border-b border-transparent focus:border-indigo-300 px-1"
                                                value={item.text}
                                                onChange={(e) => handleEditChecklistText(item.id, e.target.value)}
                                            />
                                        ) : (
                                            <span className={`flex-grow text-sm ${item.isCompleted ? 'line-through text-gray-400' : 'text-gray-700'}`}>{item.text}</span>
                                        )}

                                        {(isEditing || (!isEditing && !item.isCompleted)) && (
                                            <button 
                                                onClick={() => isEditing ? handleRemoveChecklistItemEdit(item.id) : handleDeleteChecklistItem(item.id)} 
                                                className={`text-red-300 hover:text-red-500 ${!isEditing ? 'opacity-0 group-hover:opacity-100' : ''} transition-opacity`}
                                            >
                                                <IconTrash className="w-4 h-4" />
                                            </button>
                                        )}
                                    </div>
                                ))}
                            </div>

                            <div className="flex gap-2">
                                <input 
                                    className="flex-grow px-3 py-2 text-sm border border-gray-300 rounded-lg outline-none focus:border-indigo-500" 
                                    placeholder={t.itemPlaceholder} 
                                    value={tempChecklistItem} 
                                    onChange={e => setTempChecklistItem(e.target.value)} 
                                    onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); isEditing ? handleAddChecklistItemEdit() : handleAddChecklistItemView(); } }}
                                />
                                <button onClick={isEditing ? handleAddChecklistItemEdit : handleAddChecklistItemView} className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-indigo-700">+</button>
                            </div>
                        </div>

                        {/* Priority & Team Section */}
                        {isEditing ? (
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-xs font-bold text-gray-500 mb-1">{t.priority}</label>
                                    <select 
                                        className="w-full px-3 py-2 border border-gray-300 rounded-lg bg-white"
                                        value={editingTaskData.priority}
                                        onChange={e => setEditingTaskData({...editingTaskData, priority: e.target.value as any})}
                                    >
                                        <option value="Low">{t.low}</option>
                                        <option value="Medium">{t.medium}</option>
                                        <option value="High">{t.high}</option>
                                    </select>
                                </div>
                                <div>
                                    <label className="block text-xs font-bold text-gray-500 mb-1">{t.team}</label>
                                    <div className="flex flex-wrap gap-2 p-2 border border-gray-300 rounded-lg max-h-32 overflow-y-auto bg-white">
                                        {personnel.map(p => (
                                            <button 
                                                key={p.id} 
                                                type="button" 
                                                onClick={() => toggleAssigneeEdit(p.id)} 
                                                className={`px-2 py-1 rounded text-xs font-bold border transition-colors ${editingTaskData.assigneeIds?.includes(p.id) ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-gray-50 text-gray-600 border-gray-200'}`}
                                            >
                                                {p.fullName}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            </div>
                        ) : (
                            <div>
                                <h4 className="font-bold text-gray-700 mb-3 flex items-center gap-2 text-sm"><IconUsers className="w-4 h-4" /> {t.team}</h4>
                                <div className="flex flex-wrap gap-3">
                                    {selectedTask.assigneeIds.map(uid => { 
                                        const p = personnel.find(per => per.id === uid); 
                                        return (
                                            <div key={uid} className="flex items-center gap-2 bg-gray-50 px-3 py-1.5 rounded-lg border border-gray-200">
                                                <div className="w-6 h-6 rounded-full bg-gray-200 overflow-hidden flex items-center justify-center text-xs">
                                                    {p?.avatar ? <img src={p.avatar} className="w-full h-full object-cover" /> : p?.fullName.charAt(0)}
                                                </div>
                                                <span className="text-sm font-medium">{p?.fullName}</span>
                                            </div>
                                        ); 
                                    })}
                                </div>
                            </div>
                        )}

                        {/* Edit Actions */}
                        {isEditing && (
                            <div className="flex justify-end gap-3 pt-4 border-t border-gray-100">
                                <button onClick={() => setIsEditing(false)} className="px-6 py-2 bg-gray-100 text-gray-700 rounded-xl font-medium hover:bg-gray-200">{t.cancel}</button>
                                <button onClick={handleSaveEdit} className="px-6 py-2 bg-green-600 text-white rounded-xl font-bold hover:bg-green-700 shadow-lg shadow-green-200">{t.save}</button>
                            </div>
                        )}

                        {/* Comments Section (Always visible, separate from edit) */}
                        {!isEditing && (
                            <div className="border-t border-gray-100 pt-4">
                                <h4 className="font-bold text-gray-700 mb-4 flex items-center gap-2 text-sm">
                                    <IconMessageSquare className="w-4 h-4" /> {t.chat} ({selectedTask.comments?.length || 0})
                                </h4>
                                <div className="space-y-4 mb-4">
                                    {selectedTask.comments?.map((comment, idx) => (
                                        <div key={idx} className={`flex gap-3 ${comment.authorId === currentUser.id ? 'flex-row-reverse' : ''}`}>
                                            <div className="w-8 h-8 rounded-full bg-indigo-100 flex items-center justify-center text-xs font-bold text-indigo-600 shrink-0">{comment.authorName.charAt(0)}</div>
                                            <div className={`p-3 rounded-xl max-w-[80%] text-sm ${comment.authorId === currentUser.id ? 'bg-indigo-600 text-white rounded-tl-none' : 'bg-gray-100 text-gray-700 rounded-tr-none'}`}>
                                                <div className="font-bold text-xs mb-1 opacity-80">{comment.authorName}</div>
                                                {comment.text}
                                                <div className="text-[9px] mt-1 opacity-60 dir-ltr text-right">{new Date(comment.timestamp).toLocaleTimeString(lang === 'fa' ? 'fa-IR' : 'en-US', {hour: '2-digit', minute:'2-digit'})}</div>
                                            </div>
                                        </div>
                                    ))}
                                    <div ref={commentsEndRef} />
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Comment Input (Hidden in Edit Mode) */}
                    {!isEditing && (
                        <div className="p-4 bg-white border-t border-gray-200 shrink-0">
                            <div className="relative">
                                <input 
                                    className="w-full ltr:pl-4 ltr:pr-12 rtl:pr-4 rtl:pl-12 py-3 bg-gray-50 border border-gray-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" 
                                    placeholder={t.writeMsg} 
                                    value={newComment} 
                                    onChange={e => setNewComment(e.target.value)} 
                                    onKeyDown={e => e.key === 'Enter' && handleAddComment()} 
                                />
                                <div className="absolute rtl:left-10 ltr:right-10 bottom-1">
                                    <button onClick={() => setShowMentionList(!showMentionList)} className="text-gray-400 hover:text-indigo-600 p-2 rounded-lg transition-colors" title={t.mention}>@</button>
                                    {showMentionList && (
                                        <div className="absolute bottom-10 left-0 w-48 bg-white border border-gray-200 rounded-xl shadow-xl max-h-48 overflow-y-auto z-20">
                                            {personnel.map(p => (
                                                <button key={p.id} onClick={() => handleInsertMention(p.username)} className="w-full text-start px-3 py-2 text-xs hover:bg-indigo-50 text-gray-700 border-b border-gray-50 last:border-0">
                                                    <span className="font-bold">{p.fullName}</span>
                                                    <span className="block text-gray-400 font-mono">@{p.username}</span>
                                                </button>
                                            ))}
                                        </div>
                                    )}
                                </div>
                                <button onClick={handleAddComment} disabled={!newComment.trim()} className="absolute rtl:left-2 ltr:right-2 top-2 bottom-2 bg-indigo-600 text-white px-3 rounded-lg hover:bg-indigo-700 disabled:opacity-50">
                                    <IconSend className="w-4 h-4" />
                                </button>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Task, Personnel, TaskComment, InternalMessage, TaskChecklistItem } from '../types';
import { IconCheckSquare, IconPlus, IconList, IconUsers, IconMessageSquare, IconTrash, IconClock, IconSend, IconEdit, IconCheck, IconSearch } from './Icons';
import { saveTaskToCloud, updateTaskInCloud, deleteTaskFromCloud, sendInternalMessage } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  tasks: Task[];
  lang: Language;
}

export const TaskManager: React.FC<Props> = ({ currentUser, personnel, tasks, lang }) => {
  const [showAddModal, setShowAddModal] = useState(false);
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [isEditing, setIsEditing] = useState(false); // State to toggle edit mode
  const [editingTaskData, setEditingTaskData] = useState<Partial<Task>>({}); // State for editing data

  const [filterMode, setFilterMode] = useState<'my' | 'assigned' | 'all'>('my');
  const [newTaskTitle, setNewTaskTitle] = useState('');
  const [newTaskDesc, setNewTaskDesc] = useState('');
  const [newTaskPriority, setNewTaskPriority] = useState<'Low' | 'Medium' | 'High'>('Medium');
  const [newTaskAssignees, setNewTaskAssignees] = useState<string[]>([currentUser.id]);
  const [newTaskChecklist, setNewTaskChecklist] = useState<TaskChecklistItem[]>([]);
  const [tempChecklistItem, setTempChecklistItem] = useState('');

  // Comment states
  const [newComment, setNewComment] = useState('');
  const [showMentionList, setShowMentionList] = useState(false);
  const commentsEndRef = useRef<HTMLDivElement>(null);
  const isAdmin = currentUser.roles.includes('مدیر') || currentUser.username === 'master';

  const t = {
      fa: {
          header: 'امور روزانه و وظایف تیمی',
          sub: 'مدیریت لیست کارها، چک‌لیست‌ها و پیگیری',
          myTasks: 'کارهای من',
          assigned: 'محول شده‌ها',
          all: 'همه',
          newTask: 'تعریف کار جدید',
          title: 'عنوان کار',
          desc: 'توضیحات',
          checklist: 'چک‌لیست / زیرمجموعه کارها',
          add: 'افزودن',
          priority: 'اولویت',
          team: 'انجام دهندگان (تیم)',
          create: 'ثبت وظیفه',
          chat: 'گفتگو و پیگیری',
          writeMsg: 'نوشتن پیام...',
          deleteConfirm: 'آیا از حذف این وظیفه اطمینان دارید؟',
          low: 'پایین',
          medium: 'عادی',
          high: 'فوری',
          empty: 'لیست کارها خالی است.',
          mention: 'منشن کردن همکار (@)',
          edit: 'ویرایش',
          save: 'ذخیره تغییرات',
          cancel: 'انصراف',
          itemPlaceholder: 'آیتم جدید...'
      },
      en: {
          header: 'Daily Tasks & Team Work',
          sub: 'Manage tasks, checklists and tracking',
          myTasks: 'My Tasks',
          assigned: 'Assigned by Me',
          all: 'All',
          newTask: 'New Task',
          title: 'Title',
          desc: 'Description',
          checklist: 'Checklist / Subtasks',
          add: 'Add',
          priority: 'Priority',
          team: 'Assignees',
          create: 'Create Task',
          chat: 'Chat & Tracking',
          writeMsg: 'Write a comment...',
          deleteConfirm: 'Are you sure you want to delete this task?',
          low: 'Low',
          medium: 'Normal',
          high: 'Urgent',
          empty: 'No tasks found.',
          mention: 'Mention colleague (@)',
          edit: 'Edit',
          save: 'Save Changes',
          cancel: 'Cancel',
          itemPlaceholder: 'New item...'
      }
  }[lang];

  useEffect(() => {
    if (selectedTask && commentsEndRef.current) { commentsEndRef.current.scrollIntoView({ behavior: 'smooth' }); }
  }, [selectedTask?.comments?.length]);

  // Reset editing state when modal closes
  useEffect(() => {
      if (!selectedTask) {
          setIsEditing(false);
          setEditingTaskData({});
      }
  }, [selectedTask]);

  const filteredTasks = tasks.filter(task => {
      if (filterMode === 'my') return task.assigneeIds.includes(currentUser.id);
      if (filterMode === 'assigned') return task.creatorId === currentUser.id;
      return true;
  });

  const handleAddChecklistItemCreate = () => {
      if (!tempChecklistItem.trim()) return;
      setNewTaskChecklist(prev => [...prev, { id: `cl-${Date.now()}`, text: tempChecklistItem, isCompleted: false }]);
      setTempChecklistItem('');
  };

  const handleCreateTask = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!newTaskTitle.trim()) return;
      const newTask: Task = { id: `task-${Date.now()}`, title: newTaskTitle, description: newTaskDesc, creatorId: currentUser.id, creatorName: currentUser.fullName, assigneeIds: newTaskAssignees, isCompleted: false, priority: newTaskPriority, createdAt: new Date().toISOString(), checklist: newTaskChecklist, comments: [] };
      await saveTaskToCloud(newTask);
      setShowAddModal(false); setNewTaskTitle(''); setNewTaskDesc(''); setNewTaskAssignees([currentUser.id]); setNewTaskChecklist([]); setTempChecklistItem('');
  };

  const toggleTaskCompletion = async (task: Task) => { await updateTaskInCloud(task.id, { isCompleted: !task.isCompleted }); };
  const handleDeleteTask = async (id: string) => { if (window.confirm(t.deleteConfirm)) { await deleteTaskFromCloud(id); if (selectedTask?.id === id) setSelectedTask(null); } };

  // --- Editing Logic ---
  const handleStartEdit = () => {
      if (!selectedTask) return;
      setEditingTaskData({
          title: selectedTask.title,
          description: selectedTask.description,
          priority: selectedTask.priority,
          assigneeIds: selectedTask.assigneeIds,
          checklist: selectedTask.checklist || []
      });
      setIsEditing(true);
  };

  const handleSaveEdit = async () => {
      if (!selectedTask || !editingTaskData.title) return;
      await updateTaskInCloud(selectedTask.id, editingTaskData);

      // Update local state to reflect changes immediately
      setSelectedTask({ ...selectedTask, ...editingTaskData } as Task);
      setIsEditing(false);
  };

  const handleEditChecklistText = (id: string, text: string) => {
      setEditingTaskData(prev => ({
          ...prev,
          checklist: prev.checklist?.map(item => item.id === id ? { ...item, text } : item)
      }));
  };

  const handleAddChecklistItemEdit = () => {
      if (!tempChecklistItem.trim()) return;
      const newItem: TaskChecklistItem = { id: `cl-${Date.now()}`, text: tempChecklistItem, isCompleted: false };
      setEditingTaskData(prev => ({
          ...prev,
          checklist: [...(prev.checklist || []), newItem]
      }));
      setTempChecklistItem('');
  };

  const handleRemoveChecklistItemEdit = (id: string) => {
      setEditingTaskData(prev => ({
          ...prev,
          checklist: prev.checklist?.filter(item => item.id !== id)
      }));
  };

  const toggleAssigneeEdit = (userId: string) => {
      setEditingTaskData(prev => {
          const currentIds = prev.assigneeIds || [];
          if (currentIds.includes(userId)) {
              return { ...prev, assigneeIds: currentIds.filter(id => id !== userId) };
          } else {
              return { ...prev, assigneeIds: [...currentIds, userId] };
          }
      });
  };
  // ---------------------

  const processMentions = async (text: string, sourceTitle: string, sourceId: string) => {
      const mentionRegex = /@([a-zA-Z0-9_]+)/g;
      const matches = text.match(mentionRegex);
      if (!matches) return;
      const uniqueMentions = [...new Set(matches)];
      for (const mention of uniqueMentions) {
          const username = mention.substring(1);
          const targetUser = personnel.find(p => p.username === username);
          if (targetUser && targetUser.id !== currentUser.id) {
              const msg: InternalMessage = { id: `n-${Date.now()}-${Math.random()}`, senderId: currentUser.id, senderName: 'System', recipientIds: [targetUser.id], recipientNames: [targetUser.fullName], subject: `Mentioned in Task "${sourceTitle}"`, body: `${currentUser.fullName} mentioned you:\n\n"${text}"\n\nTask ID: ${sourceId}`, createdAt: new Date().toISOString(), readBy: [] };
              await sendInternalMessage(msg);
          }
      }
  };

  const handleAddComment = async () => {
      if (!selectedTask || !newComment.trim()) return;
      await processMentions(newComment, selectedTask.title, selectedTask.id);
      const comment: TaskComment = { id: `cm-${Date.now()}`, authorId: currentUser.id, authorName: currentUser.fullName, text: newComment, timestamp: new Date().toISOString() };
      const updatedComments = [...(selectedTask.comments || []), comment];
      await updateTaskInCloud(selectedTask.id, { comments: updatedComments });
      setSelectedTask({ ...selectedTask, comments: updatedComments });
      setNewComment(''); setShowMentionList(false);
  };

  const handleInsertMention = (username: string) => { setNewComment(prev => prev + `@${username} `); setShowMentionList(false); };

  // Checklist Toggle (View Mode)
  const handleToggleChecklist = async (itemId: string) => { 
      if (!selectedTask) return; 
      const updatedChecklist = (selectedTask.checklist || []).map(item => item.id === itemId ? { ...item, isCompleted: !item.isCompleted } : item); 
      await updateTaskInCloud(selectedTask.id, { checklist: updatedChecklist }); 
      setSelectedTask({ ...selectedTask, checklist: updatedChecklist }); 
  };

  // Checklist Delete (View Mode) - kept for quick action if needed, though edit mode is better
  const handleDeleteChecklistItem = async (itemId: string) => { 
      if (!selectedTask) return; 
      if(!window.confirm('Delete item?')) return;
      const updatedChecklist = (selectedTask.checklist || []).filter(item => item.id !== itemId); 
      await updateTaskInCloud(selectedTask.id, { checklist: updatedChecklist }); 
      setSelectedTask({ ...selectedTask, checklist: updatedChecklist }); 
  };

  // Checklist Add (View Mode)
  const handleAddChecklistItemView = async () => { 
      if (!selectedTask || !tempChecklistItem.trim()) return; 
      const newItem: TaskChecklistItem = { id: `cl-${Date.now()}`, text: tempChecklistItem, isCompleted: false }; 
      const updatedChecklist = [...(selectedTask.checklist || []), newItem]; 
      await updateTaskInCloud(selectedTask.id, { checklist: updatedChecklist }); 
      setSelectedTask({ ...selectedTask, checklist: updatedChecklist }); 
      setTempChecklistItem(''); 
  };

  const getPriorityColor = (p: string) => { if (p === 'High') return 'bg-red-100 text-red-600 border-red-200'; if (p === 'Medium') return 'bg-yellow-100 text-yellow-700 border-yellow-200'; return 'bg-blue-100 text-blue-600 border-blue-200'; };
  const calculateProgress = (checklist: TaskChecklistItem[] = []) => { if (checklist.length === 0) return 0; const completed = checklist.filter(i => i.isCompleted).length; return Math.round((completed / checklist.length) * 100); };

  return (
    <div className="space-y-6 animate-fade-in">
        <div className="flex flex-col md:flex-row justify-between items-center bg-white p-6 rounded-2xl border border-gray-100 shadow-sm gap-4"><div><h2 className="text-xl font-bold text-gray-800 flex items-center gap-2"><div className="bg-indigo-100 text-indigo-600 p-2 rounded-lg"><IconList className="w-6 h-6" /></div>{t.header}</h2><p className="text-sm text-gray-500 mt-1">{t.sub}</p></div><div className="flex gap-2"><div className="flex bg-gray-100 p-1 rounded-lg"><button onClick={() => setFilterMode('my')} className={`px-4 py-1.5 rounded-md text-sm font-bold transition-all ${filterMode === 'my' ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}>{t.myTasks}</button><button onClick={() => setFilterMode('assigned')} className={`px-4 py-1.5 rounded-md text-sm font-bold transition-all ${filterMode === 'assigned' ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}>{t.assigned}</button>{isAdmin && <button onClick={() => setFilterMode('all')} className={`px-4 py-1.5 rounded-md text-sm font-bold transition-all ${filterMode === 'all' ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}>{t.all}</button>}</div><button onClick={() => setShowAddModal(true)} className="bg-indigo-600 text-white px-4 py-2 rounded-xl font-bold hover:bg-indigo-700 flex items-center gap-2 shadow-lg shadow-indigo-200"><IconPlus className="w-5 h-5" /> {t.newTask}</button></div></div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredTasks.map(task => { 
                const progress = calculateProgress(task.checklist); 
                return (
                    <div key={task.id} className={`bg-white rounded-2xl border shadow-sm p-4 transition-all hover:shadow-md relative flex flex-col ${task.isCompleted ? 'border-gray-200 bg-gray-50' : 'border-gray-200'}`}>
                        <div className="flex justify-between items-start mb-3">
                            <div className="flex items-center gap-3">
                                <button onClick={() => toggleTaskCompletion(task)} className={`w-6 h-6 rounded border flex items-center justify-center transition-colors ${task.isCompleted ? 'bg-green-500 border-green-500 text-white' : 'border-gray-300 hover:border-indigo-500'}`}>{task.isCompleted && <IconCheckSquare className="w-4 h-4" />}</button>
                                <span className={`font-bold text-gray-800 cursor-pointer hover:text-indigo-600 ${task.isCompleted ? 'line-through text-gray-400' : ''}`} onClick={() => setSelectedTask(task)}>{task.title}</span>
                            </div>
                            <span className={`text-[10px] px-2 py-0.5 rounded border ${getPriorityColor(task.priority)}`}>{task.priority}</span>
                        </div>
                        <p className={`text-sm text-gray-500 mb-4 line-clamp-2 cursor-pointer ${task.isCompleted ? 'line-through opacity-50' : ''}`} onClick={() => setSelectedTask(task)}>{task.description || '-'}</p>

                        {task.checklist && task.checklist.length > 0 && (
                            <div className="mb-4">
                                <div className="flex justify-between text-[10px] text-gray-400 mb-1"><span>{t.checklist}</span><span>{progress}%</span></div>
                                <div className="w-full bg-gray-100 rounded-full h-1.5 overflow-hidden"><div className="bg-green-500 h-full rounded-full transition-all" style={{ width: `${progress}%` }}></div></div>
                            </div>
                        )}

                        <div className="mt-auto flex justify-between items-end border-t border-gray-50 pt-3">
                            <div className="flex -space-x-2 space-x-reverse">{task.assigneeIds.map(uid => { const p = personnel.find(per => per.id === uid); return (<div key={uid} className="w-8 h-8 rounded-full bg-gray-200 border-2 border-white flex items-center justify-center text-xs font-bold text-gray-600" title={p?.fullName}>{p?.avatar ? <img src={p.avatar} className="w-full h-full rounded-full object-cover" /> : p?.fullName.charAt(0)}</div>); })}</div>
                            <div className="flex gap-2">
                                <button onClick={() => setSelectedTask(task)} className="text-gray-400 hover:text-indigo-600 flex items-center gap-1 text-xs font-bold bg-gray-50 px-2 py-1 rounded"><IconMessageSquare className="w-3 h-3" />{task.comments?.length || 0}</button>
                                {(task.creatorId === currentUser.id || isAdmin) && (<button onClick={() => handleDeleteTask(task.id)} className="text-gray-400 hover:text-red-500 p-1 rounded hover:bg-red-50"><IconTrash className="w-4 h-4" /></button>)}
                            </div>
                        </div>
                    </div>
                )
            })} 
            {filteredTasks.length === 0 && <div className="col-span-full py-12 text-center text-gray-400 bg-white rounded-2xl border border-dashed border-gray-200">{t.empty}</div>}
        </div>

        {/* CREATE TASK MODAL */}
        {showAddModal && (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4"><div className="bg-white rounded-2xl w-full max-w-lg shadow-2xl animate-fade-in flex flex-col max-h-[90vh]"><div className="p-5 border-b border-gray-100 flex justify-between items-center"><h3 className="font-bold text-gray-800">{t.newTask}</h3><button onClick={() => setShowAddModal(false)} className="text-gray-400 hover:text-gray-600">✕</button></div><div className="overflow-y-auto p-6 flex-grow"><form id="create-task-form" onSubmit={handleCreateTask} className="space-y-4"><div><label className="block text-sm font-bold text-gray-700 mb-1">{t.title}</label><input required className="w-full px-3 py-2 border border-gray-300 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500" value={newTaskTitle} onChange={e => setNewTaskTitle(e.target.value)} /></div><div><label className="block text-sm font-bold text-gray-700 mb-1">{t.desc}</label><textarea className="w-full px-3 py-2 border border-gray-300 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500" value={newTaskDesc} onChange={e => setNewTaskDesc(e.target.value)} rows={3} /></div><div className="bg-gray-50 p-3 rounded-lg border border-gray-200"><label className="block text-sm font-bold text-gray-700 mb-2">{t.checklist}</label><div className="space-y-2 mb-2">{newTaskChecklist.map((item, idx) => (<div key={idx} className="flex items-center gap-2 text-sm bg-white p-2 rounded border border-gray-200"><IconCheckSquare className="w-4 h-4 text-gray-400" /><span className="flex-grow">{item.text}</span><button type="button" onClick={() => setNewTaskChecklist(prev => prev.filter((_, i) => i !== idx))} className="text-red-400 hover:text-red-600"><IconTrash className="w-3 h-3" /></button></div>))}</div><div className="flex gap-2"><input className="flex-grow px-2 py-1.5 text-sm border border-gray-300 rounded outline-none" placeholder="..." value={tempChecklistItem} onChange={e => setTempChecklistItem(e.target.value)} onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); handleAddChecklistItemCreate(); } }} /><button type="button" onClick={handleAddChecklistItemCreate} className="bg-indigo-50 text-indigo-600 px-3 rounded text-xs font-bold border border-indigo-200 hover:bg-indigo-100">{t.add}</button></div></div><div className="grid grid-cols-2 gap-4"><div><label className="block text-sm font-bold text-gray-700 mb-1">{t.priority}</label><select className="w-full px-3 py-2 border border-gray-300 rounded-lg bg-white" value={newTaskPriority} onChange={e => setNewTaskPriority(e.target.value as any)}><option value="Low">{t.low}</option><option value="Medium">{t.medium}</option><option value="High">{t.high}</option></select></div></div><div><label className="block text-sm font-bold text-gray-700 mb-1">{t.team}</label><div className="flex flex-wrap gap-2 p-2 border border-gray-300 rounded-lg max-h-32 overflow-y-auto">{personnel.map(p => (<button key={p.id} type="button" onClick={() => setNewTaskAssignees(prev => prev.includes(p.id) ? prev.filter(id => id !== p.id) : [...prev, p.id])} className={`px-2 py-1 rounded text-xs font-bold border ${newTaskAssignees.includes(p.id) ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-gray-50 text-gray-600 border-gray-200'}`}>{p.fullName}</button>))}</div></div></form></div><div className="p-4 border-t border-gray-100 flex justify-end"><button type="submit" form="create-task-form" className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold hover:bg-indigo-700 shadow-lg shadow-indigo-200">{t.create}</button></div></div></div>
        )}

        {/* DETAIL & EDIT TASK MODAL */}
        {selectedTask && (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
                <div className="bg-white rounded-2xl w-full max-w-2xl h-[85vh] shadow-2xl animate-fade-in flex flex-col overflow-hidden">
                    <div className="p-5 border-b border-gray-100 flex justify-between items-start bg-gray-50 shrink-0">
                        <div className="w-full">
                            {isEditing ? (
                                <input 
                                    className="w-full text-xl font-bold text-gray-800 bg-white border border-gray-300 rounded px-2 py-1 outline-none focus:ring-2 focus:ring-indigo-500"
                                    value={editingTaskData.title || ''}
                                    onChange={e => setEditingTaskData({...editingTaskData, title: e.target.value})}
                                    placeholder={t.title}
                                />
                            ) : (
                                <div className="flex items-center gap-2 mb-1">
                                    <span className={`text-[10px] px-2 py-0.5 rounded border ${getPriorityColor(selectedTask.priority)}`}>{selectedTask.priority}</span>
                                    <span className="text-xs text-gray-400 dir-ltr">{new Date(selectedTask.createdAt).toLocaleString(lang === 'fa' ? 'fa-IR' : 'en-US')}</span>
                                    <h3 className={`font-bold text-xl text-gray-800 ${selectedTask.isCompleted ? 'line-through text-gray-400' : ''}`}>{selectedTask.title}</h3>
                                </div>
                            )}
                        </div>
                        <div className="flex gap-2 shrink-0 ml-4">
                            {!isEditing && (
                                <button onClick={handleStartEdit} className="text-gray-500 hover:text-indigo-600 p-1 rounded hover:bg-indigo-50">
                                    <IconEdit className="w-5 h-5" />
                                </button>
                            )}
                            <button onClick={() => setSelectedTask(null)} className="text-gray-400 hover:text-red-600 p-1 rounded hover:bg-red-50">✕</button>
                        </div>
                    </div>

                    <div className="flex-grow overflow-y-auto p-6 space-y-6">
                        {/* Description Section */}
                        {isEditing ? (
                            <div>
                                <label className="block text-xs font-bold text-gray-500 mb-1">{t.desc}</label>
                                <textarea 
                                    className="w-full p-3 border border-gray-300 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500 min-h-[100px]"
                                    value={editingTaskData.description || ''}
                                    onChange={e => setEditingTaskData({...editingTaskData, description: e.target.value})}
                                />
                            </div>
                        ) : (
                            <div className="bg-white p-4 rounded-xl border border-gray-100 text-gray-700 leading-relaxed whitespace-pre-wrap">
                                {selectedTask.description || '-'}
                            </div>
                        )}

                        {/* Checklist Section */}
                        <div className="bg-gray-50 rounded-xl border border-gray-200 p-4">
                            <div className="flex justify-between items-center mb-3">
                                <h4 className="font-bold text-gray-700 flex items-center gap-2 text-sm">
                                    <IconList className="w-4 h-4 text-indigo-500" /> {t.checklist}
                                </h4>
                                {!isEditing && <span className="text-xs font-bold text-indigo-600 bg-indigo-50 px-2 py-1 rounded">{calculateProgress(selectedTask.checklist)}%</span>}
                            </div>

                            <div className="space-y-2 mb-3">
                                {(isEditing ? (editingTaskData.checklist || []) : (selectedTask.checklist || [])).map(item => (
                                    <div key={item.id} className={`flex items-center gap-3 bg-white p-2 rounded-lg border ${isEditing ? 'border-gray-300' : 'border-gray-200 hover:border-indigo-300'} transition-colors group`}>
                                        {!isEditing && (
                                            <input type="checkbox" checked={item.isCompleted} onChange={() => handleToggleChecklist(item.id)} className="w-5 h-5 text-green-600 rounded cursor-pointer"/>
                                        )}

                                        {isEditing ? (
                                            <input 
                                                className="flex-grow text-sm outline-none border-b border-transparent focus:border-indigo-300 px-1"
                                                value={item.text}
                                                onChange={(e) => handleEditChecklistText(item.id, e.target.value)}
                                            />
                                        ) : (
                                            <span className={`flex-grow text-sm ${item.isCompleted ? 'line-through text-gray-400' : 'text-gray-700'}`}>{item.text}</span>
                                        )}

                                        {(isEditing || (!isEditing && !item.isCompleted)) && (
                                            <button 
                                                onClick={() => isEditing ? handleRemoveChecklistItemEdit(item.id) : handleDeleteChecklistItem(item.id)} 
                                                className={`text-red-300 hover:text-red-500 ${!isEditing ? 'opacity-0 group-hover:opacity-100' : ''} transition-opacity`}
                                            >
                                                <IconTrash className="w-4 h-4" />
                                            </button>
                                        )}
                                    </div>
                                ))}
                            </div>

                            <div className="flex gap-2">
                                <input 
                                    className="flex-grow px-3 py-2 text-sm border border-gray-300 rounded-lg outline-none focus:border-indigo-500" 
                                    placeholder={t.itemPlaceholder} 
                                    value={tempChecklistItem} 
                                    onChange={e => setTempChecklistItem(e.target.value)} 
                                    onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); isEditing ? handleAddChecklistItemEdit() : handleAddChecklistItemView(); } }}
                                />
                                <button onClick={isEditing ? handleAddChecklistItemEdit : handleAddChecklistItemView} className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-indigo-700">+</button>
                            </div>
                        </div>

                        {/* Priority & Team Section */}
                        {isEditing ? (
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-xs font-bold text-gray-500 mb-1">{t.priority}</label>
                                    <select 
                                        className="w-full px-3 py-2 border border-gray-300 rounded-lg bg-white"
                                        value={editingTaskData.priority}
                                        onChange={e => setEditingTaskData({...editingTaskData, priority: e.target.value as any})}
                                    >
                                        <option value="Low">{t.low}</option>
                                        <option value="Medium">{t.medium}</option>
                                        <option value="High">{t.high}</option>
                                    </select>
                                </div>
                                <div>
                                    <label className="block text-xs font-bold text-gray-500 mb-1">{t.team}</label>
                                    <div className="flex flex-wrap gap-2 p-2 border border-gray-300 rounded-lg max-h-32 overflow-y-auto bg-white">
                                        {personnel.map(p => (
                                            <button 
                                                key={p.id} 
                                                type="button" 
                                                onClick={() => toggleAssigneeEdit(p.id)} 
                                                className={`px-2 py-1 rounded text-xs font-bold border transition-colors ${editingTaskData.assigneeIds?.includes(p.id) ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-gray-50 text-gray-600 border-gray-200'}`}
                                            >
                                                {p.fullName}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            </div>
                        ) : (
                            <div>
                                <h4 className="font-bold text-gray-700 mb-3 flex items-center gap-2 text-sm"><IconUsers className="w-4 h-4" /> {t.team}</h4>
                                <div className="flex flex-wrap gap-3">
                                    {selectedTask.assigneeIds.map(uid => { 
                                        const p = personnel.find(per => per.id === uid); 
                                        return (
                                            <div key={uid} className="flex items-center gap-2 bg-gray-50 px-3 py-1.5 rounded-lg border border-gray-200">
                                                <div className="w-6 h-6 rounded-full bg-gray-200 overflow-hidden flex items-center justify-center text-xs">
                                                    {p?.avatar ? <img src={p.avatar} className="w-full h-full object-cover" /> : p?.fullName.charAt(0)}
                                                </div>
                                                <span className="text-sm font-medium">{p?.fullName}</span>
                                            </div>
                                        ); 
                                    })}
                                </div>
                            </div>
                        )}

                        {/* Edit Actions */}
                        {isEditing && (
                            <div className="flex justify-end gap-3 pt-4 border-t border-gray-100">
                                <button onClick={() => setIsEditing(false)} className="px-6 py-2 bg-gray-100 text-gray-700 rounded-xl font-medium hover:bg-gray-200">{t.cancel}</button>
                                <button onClick={handleSaveEdit} className="px-6 py-2 bg-green-600 text-white rounded-xl font-bold hover:bg-green-700 shadow-lg shadow-green-200">{t.save}</button>
                            </div>
                        )}

                        {/* Comments Section (Always visible, separate from edit) */}
                        {!isEditing && (
                            <div className="border-t border-gray-100 pt-4">
                                <h4 className="font-bold text-gray-700 mb-4 flex items-center gap-2 text-sm">
                                    <IconMessageSquare className="w-4 h-4" /> {t.chat} ({selectedTask.comments?.length || 0})
                                </h4>
                                <div className="space-y-4 mb-4">
                                    {selectedTask.comments?.map((comment, idx) => (
                                        <div key={idx} className={`flex gap-3 ${comment.authorId === currentUser.id ? 'flex-row-reverse' : ''}`}>
                                            <div className="w-8 h-8 rounded-full bg-indigo-100 flex items-center justify-center text-xs font-bold text-indigo-600 shrink-0">{comment.authorName.charAt(0)}</div>
                                            <div className={`p-3 rounded-xl max-w-[80%] text-sm ${comment.authorId === currentUser.id ? 'bg-indigo-600 text-white rounded-tl-none' : 'bg-gray-100 text-gray-700 rounded-tr-none'}`}>
                                                <div className="font-bold text-xs mb-1 opacity-80">{comment.authorName}</div>
                                                {comment.text}
                                                <div className="text-[9px] mt-1 opacity-60 dir-ltr text-right">{new Date(comment.timestamp).toLocaleTimeString(lang === 'fa' ? 'fa-IR' : 'en-US', {hour: '2-digit', minute:'2-digit'})}</div>
                                            </div>
                                        </div>
                                    ))}
                                    <div ref={commentsEndRef} />
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Comment Input (Hidden in Edit Mode) */}
                    {!isEditing && (
                        <div className="p-4 bg-white border-t border-gray-200 shrink-0">
                            <div className="relative">
                                <input 
                                    className="w-full ltr:pl-4 ltr:pr-12 rtl:pr-4 rtl:pl-12 py-3 bg-gray-50 border border-gray-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" 
                                    placeholder={t.writeMsg} 
                                    value={newComment} 
                                    onChange={e => setNewComment(e.target.value)} 
                                    onKeyDown={e => e.key === 'Enter' && handleAddComment()} 
                                />
                                <div className="absolute rtl:left-10 ltr:right-10 bottom-1">
                                    <button onClick={() => setShowMentionList(!showMentionList)} className="text-gray-400 hover:text-indigo-600 p-2 rounded-lg transition-colors" title={t.mention}>@</button>
                                    {showMentionList && (
                                        <div className="absolute bottom-10 left-0 w-48 bg-white border border-gray-200 rounded-xl shadow-xl max-h-48 overflow-y-auto z-20">
                                            {personnel.map(p => (
                                                <button key={p.id} onClick={() => handleInsertMention(p.username)} className="w-full text-start px-3 py-2 text-xs hover:bg-indigo-50 text-gray-700 border-b border-gray-50 last:border-0">
                                                    <span className="font-bold">{p.fullName}</span>
                                                    <span className="block text-gray-400 font-mono">@{p.username}</span>
                                                </button>
                                            ))}
                                        </div>
                                    )}
                                </div>
                                <button onClick={handleAddComment} disabled={!newComment.trim()} className="absolute rtl:left-2 ltr:right-2 top-2 bottom-2 bg-indigo-600 text-white px-3 rounded-lg hover:bg-indigo-700 disabled:opacity-50">
                                    <IconSend className="w-4 h-4" />
                                </button>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Ticket, TicketStatus, ServiceOption, Personnel, Customer, AppConfig, ProjectDetails, AttachedFile, Currency, Payment, InternalMessage, Invoice, Task, Meeting, SystemLog, ProjectMilestone, ProjectRisk, ProjectTeamMember, KPI, CustomForm } from '../types';
import { IconCheck, IconActivity, IconUsers, IconBriefcase, IconLayout, IconPaperclip, IconShield, IconSettings, IconClock, IconFile, IconEdit, IconTrash, IconProject, IconMoney, IconUpload, IconPlus, IconChart, IconMail, IconInvoice, IconList, IconCalendarClock, IconHistory, IconCopy, IconSearch, IconFlag, IconAlertTriangle, IconTime, IconTrendingUp, IconRefreshCw, IconLock, IconMegaphone, IconBarChart2, IconMapPin, IconWhatsapp, IconTarget, IconClipboard, IconFolder } from './Icons';
import { ServiceManager } from './ServiceManager';
import { PersonnelManager } from './PersonnelManager';
import { CustomerManager } from './CustomerManager';
import { SettingsManager } from './SettingsManager';
import { InternalMessenger } from './InternalMessenger';
import { InvoiceModal } from './InvoiceModal';
import { TaskManager } from './TaskManager';
import { MeetingCalendar } from './MeetingCalendar';
import { PerformanceReports } from './PerformanceReports';
import { KPIManager } from './KPIManager';
import { uploadFileWithProgress, logSystemAction, subscribeToSystemLogs, saveTaskToCloud, restoreEntityFromLog, sendInternalMessage, subscribeToCustomForms } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  tickets: Ticket[];
  services: ServiceOption[];
  personnel: Personnel[];
  customers: Customer[];
  messages: InternalMessage[];
  tasks: Task[]; 
  meetings: Meeting[]; 
  kpis?: KPI[];
  config: AppConfig;
  onCreateTicket: (ticket: Ticket) => Promise<void>;
  onUpdateTicket: (ticketId: string, updates: Partial<Ticket>, actorName: string, actionNote?: string, visibility?: 'public' | 'internal') => void;
  onDeleteTicket: (ticketId: string) => Promise<void>;
  onUpdateServices: (services: ServiceOption[]) => void;
  onUpdatePersonnel: (personnel: Personnel[]) => void;
  onUpdateCustomers: (customers: Customer[]) => void; 
  onEditCustomer: (id: string, updates: Partial<Customer>) => Promise<void>;
  onDeleteCustomer: (id: string) => Promise<void>;
  onUpdateConfig: (config: AppConfig) => void;
  onLogout: () => void;
  lang: Language;
}

export const AdminDashboard: React.FC<Props> = ({ 
  currentUser,
  tickets, 
  services, 
  personnel, 
  customers,
  messages,
  tasks,
  meetings,
  kpis = [],
  config,
  onCreateTicket,
  onUpdateTicket,
  onDeleteTicket,
  onUpdateServices,
  onUpdatePersonnel,
  onUpdateCustomers,
  onEditCustomer,
  onDeleteCustomer,
  onUpdateConfig,
  onLogout,
  lang
}) => {
  const safeRoles = currentUser?.roles || [];
  const isAdmin = safeRoles.includes('مدیر');
  const isMaster = currentUser?.username === 'master';

  const canManageInvoices = isAdmin || isMaster || currentUser?.permissions?.canIssueInvoices; 
  const canAssign = isAdmin || isMaster || currentUser?.permissions?.canAssign;
