      const newTicketId = `PROJ-${Math.floor(10000 + Math.random() * 90000)}`;
      const newTicket: Ticket = {
          id: newTicketId,
          customerName: newProjectData.customerName,
          phoneNumber: newProjectData.phoneNumber,
          whatsappNumber: newProjectData.phoneNumber,
          location: 'N/A',
          serviceId: newProjectData.serviceId,
          description: `Project: ${newProjectData.title}`,
          status: TicketStatus.IN_PROGRESS,
          createdAt: new Date().toISOString(),
          priority: newProjectData.priority,
          files: [],
          timeline: [
              {
                  type: 'creation',
                  title: 'Project Created',
                  description: `Project "${newProjectData.title}" created by ${currentUser.fullName}.`,
                  actorName: currentUser.fullName,
                  timestamp: new Date().toISOString(),
                  visibility: 'public'
              }
          ],
          projectData: {
              isActive: true,
              tariff: { 
                  amount: parseInt(newProjectData.tariffAmount.replace(/,/g, '')) || 0, 
                  currency: newProjectData.tariffCurrency 
              },
              startDate: newProjectData.startDate,
              endDate: newProjectData.endDate,
              teamMemberIds: [currentUser.id],
              teamMembers: [
                  { userId: currentUser.id, role: 'Project Manager', responsibility: 'Owner', joinedAt: new Date().toISOString() }
              ],
              projectFiles: [],
              payments: [],
              invoices: [],
              milestones: [],
              risks: [],
              progress: 0,
              statusNote: 'Project Initialized.'
          },
          assignedTo: currentUser.id
      };
      try {
          await onCreateTicket(newTicket);
          setCreatedProjectId(newTicketId);
      } catch (e) {
          alert('Error creating project');
      }
  };

  const handleProjectModalClose = () => {
      setShowNewProjectModal(false);
      setCreatedProjectId(null);
      setNewProjectData({ title: '', serviceId: '', customerName: '', phoneNumber: '', startDate: '', endDate: '', tariffAmount: '', tariffCurrency: 'IRR', priority: 'Medium' });
  };

  const handleProjectFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (!e.target.files || e.target.files.length === 0) return;
      const files: File[] = Array.from(e.target.files);
      for (const file of files) {
          if (file.size > 5 * 1024 * 1024) { alert('File too large > 5MB'); continue; }
          const newFile: AttachedFile = { name: file.name, size: file.size, type: file.type, content: '', status: 'uploading', progress: 0 };
          setProjectForm(prev => ({ ...prev, projectFiles: [...prev.projectFiles, newFile] }));
          uploadFileWithProgress(
              file,
              (progress) => setProjectForm(prev => ({ ...prev, projectFiles: prev.projectFiles.map(f => f.name === file.name && f.status === 'uploading' ? { ...f, progress } : f) })),
              (url) => setProjectForm(prev => ({ ...prev, projectFiles: prev.projectFiles.map(f => f.name === file.name ? { ...f, content: url, status: 'success', progress: 100 } : f) })),
              (err) => setProjectForm(prev => ({ ...prev, projectFiles: prev.projectFiles.map(f => f.name === file.name ? { ...f, status: 'error', errorMsg: err.message } : f) }))
          );
      }
      if (projectFileInputRef.current) projectFileInputRef.current.value = '';
  };

  const handleRemoveProjectFile = (index: number) => {
      setProjectForm(prev => ({ ...prev, projectFiles: prev.projectFiles.filter((_, i) => i !== index) }));
  };

  const handleSaveInvoice = (invoice: Invoice) => {
      if (!selectedTicket) return;
      const invoices = projectForm.invoices || [];
      const existingIdx = invoices.findIndex(i => i.id === invoice.id);
      let newInvoices = existingIdx >= 0 ? invoices.map((inv, i) => i === existingIdx ? invoice : inv) : [...invoices, invoice];
      const updatedProjectData = { ...projectForm, invoices: newInvoices, isActive: true };
      onUpdateTicket(selectedTicket.id, { projectData: updatedProjectData }, currentUser.fullName, `Invoice ${invoice.number} updated.`);
      logSystemAction('UPDATE', 'Project', `Invoice ${invoice.number} saved`, currentUser.fullName, selectedTicket.id);
      setShowInvoiceModal(false);
  };

  const handleSaveProject = () => {
      if (!selectedTicket) return;
      if (projectForm.projectFiles.some(f => f.status === 'uploading')) { alert(lang === 'fa' ? 'صبر کنید...' : 'Wait for upload...'); return; }
      const updatedProjectData = { ...projectForm, isActive: true };
      onUpdateTicket(selectedTicket.id, { projectData: updatedProjectData }, currentUser.fullName, 'Project Updated');
      logSystemAction('UPDATE', 'Project', `Project ${selectedTicket.id} updated`, currentUser.fullName, selectedTicket.id);
      alert(lang === 'fa' ? 'ذخیره شد.' : 'Saved.');
  };

  const handleAddMilestone = () => {
      if (!newMilestoneTitle) return;
      const ms: ProjectMilestone = { id: `ms-${Date.now()}`, title: newMilestoneTitle, isCompleted: false, dueDate: newMilestoneDate };
      setProjectForm(prev => ({ ...prev, milestones: [...(prev.milestones || []), ms] }));
      setNewMilestoneTitle(''); setNewMilestoneDate('');
  };

