  };

  const handleDeleteMilestone = (id: string) => {
      setProjectForm(prev => ({ ...prev, milestones: prev.milestones?.filter(m => m.id !== id) }));
  };

  const handleAddRisk = () => {
      if (!newRiskTitle) return;
      const risk: ProjectRisk = { id: `risk-${Date.now()}`, title: newRiskTitle, impact: newRiskImpact };
      setProjectForm(prev => ({ ...prev, risks: [...(prev.risks || []), risk] }));
