                    { id: 'services', icon: <IconBriefcase className="w-5 h-5"/>, label: t.services, hidden: !hasTariffAccess },
                    { id: 'reports', icon: <IconChart className="w-5 h-5"/>, label: t.reports, hidden: !isAdmin },
