                                    </div>

                                    {/* Files */}
                                    <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm md:col-span-3">
                                        <h4 className="font-bold text-gray-700 mb-4">{t.projectDocs}</h4>
                                        <div className="flex items-center gap-4 mb-4">
                                            <button onClick={() => projectFileInputRef.current?.click()} className="bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2">
                                                <IconUpload className="w-4 h-4" /> Upload
                                            </button>
                                            <input type="file" ref={projectFileInputRef} className="hidden" multiple onChange={handleProjectFileUpload} />
                                            <span className="text-xs text-gray-400">{t.uploadHint}</span>
                                        </div>
                                        <div className="flex flex-wrap gap-4">
                                            {projectForm.projectFiles?.map((f, i) => (
                                                <div key={i} className="relative group bg-gray-50 border border-gray-200 p-3 rounded-xl flex items-center gap-3 w-64">
                                                    <div className="p-2 bg-white rounded-lg border border-gray-200"><IconFile className="w-5 h-5 text-blue-500" /></div>
                                                    <div className="overflow-hidden">
                                                        <a href={f.content} target="_blank" className="text-sm font-bold text-gray-800 hover:underline truncate block">{f.name}</a>
                                                        <span className="text-xs text-gray-500">{(f.size/1024/1024).toFixed(2)} MB</span>
                                                    </div>
                                                    <button onClick={() => handleRemoveProjectFile(i)} className="absolute top-2 right-2 text-red-400 opacity-0 group-hover:opacity-100 transition-opacity bg-white rounded-full p-1 shadow">×</button>
                                                    {f.status === 'uploading' && <div className="absolute bottom-0 left-0 h-1 bg-blue-500 transition-all" style={{ width: `${f.progress}%` }}></div>}
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        )}

        {/* New Project Modal */}
        {showNewProjectModal && (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
                <div className="bg-white rounded-2xl w-full max-w-lg shadow-2xl animate-fade-in">
                    <div className="p-6 border-b border-gray-100 flex justify-between items-center bg-indigo-50 rounded-t-2xl">
                        <h3 className="font-bold text-indigo-900">{t.newProject}</h3>
                        <button onClick={handleProjectModalClose} className="text-gray-400 hover:text-gray-600">✕</button>
                    </div>

                    {createdProjectId ? (
                        <div className="p-8 text-center">
                            <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4"><IconCheck className="w-8 h-8 text-green-600" /></div>
                            <h4 className="text-xl font-bold text-gray-800 mb-2">{t.successProject}</h4>
                            <p className="text-gray-500 mb-6">ID: {createdProjectId}</p>
                            <button onClick={handleProjectModalClose} className="bg-gray-100 text-gray-700 px-6 py-2 rounded-xl font-bold">{t.understand}</button>
                        </div>
                    ) : (
                        <form onSubmit={handleCreateProject} className="p-6 space-y-4">
                            <div><label className="lbl">{t.projectTitle}</label><input className="input-std" required value={newProjectData.title} onChange={e => setNewProjectData({...newProjectData, title: e.target.value})} /></div>
                            <div className="grid grid-cols-2 gap-4">
                                <div><label className="lbl">{t.customer}</label><input className="input-std" required value={newProjectData.customerName} onChange={e => setNewProjectData({...newProjectData, customerName: e.target.value})} /></div>
                                <div><label className="lbl">{t.phone}</label><input className="input-std" required value={newProjectData.phoneNumber} onChange={e => setNewProjectData({...newProjectData, phoneNumber: e.target.value})} /></div>
                            </div>
                            <div>
                                <label className="lbl">{t.relatedService}</label>
                                <select className="input-std" value={newProjectData.serviceId} onChange={e => setNewProjectData({...newProjectData, serviceId: e.target.value})}>
                                    <option value="">-</option>
                                    {services.map(s => <option key={s.id} value={s.id}>{s.title}</option>)}
                                </select>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div><label className="lbl">{t.startDate}</label><input type="date" className="input-std" required value={newProjectData.startDate} onChange={e => setNewProjectData({...newProjectData, startDate: e.target.value})} /></div>
                                <div><label className="lbl">{t.endDate}</label><input type="date" className="input-std" required value={newProjectData.endDate} onChange={e => setNewProjectData({...newProjectData, endDate: e.target.value})} /></div>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div><label className="lbl">{t.contractAmount}</label><input className="input-std" type="number" required value={newProjectData.tariffAmount} onChange={e => setNewProjectData({...newProjectData, tariffAmount: e.target.value})} /></div>
                                <div><label className="lbl">Currency</label><select className="input-std" value={newProjectData.tariffCurrency} onChange={e => setNewProjectData({...newProjectData, tariffCurrency: e.target.value as any})}><option value="IRR">IRR</option><option value="USD">USD</option><option value="OMR">OMR</option></select></div>
                            </div>
                            <div>
                                <label className="lbl">{t.priority}</label>
                                <select className="input-std" value={newProjectData.priority} onChange={e => setNewProjectData({...newProjectData, priority: e.target.value as any})}>
                                    <option value="Low">Low</option><option value="Medium">Medium</option><option value="High">High</option>
                                </select>
                            </div>
                            <div className="flex justify-end pt-4"><button type="submit" className="bg-indigo-600 text-white px-8 py-2 rounded-xl font-bold hover:bg-indigo-700 shadow-lg">{t.create}</button></div>
                        </form>
                    )}
                </div>
            </div>
        )}

        {showInvoiceModal && selectedTicket && (
            <InvoiceModal 
                customer={{ fullName: selectedTicket.customerName, companyName: selectedTicket.companyName, location: selectedTicket.location, phoneNumber: selectedTicket.phoneNumber } as Customer} 
                template={config.invoiceTemplate || { companyName: 'My Company', address: '', phone: '', footerText: '', termsConditions: '', defaultTaxRate: 0, colorTheme: '#000' }}
                onSave={handleSaveInvoice}
                onClose={() => setShowInvoiceModal(false)}
            />
        )}
    </div>
  );
};
